import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom'; // 1. Импортируем хук для навигации
import api from '../services/api';

const Catalog = () => {
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);
  const [search, setSearch] = useState('');
  const [selectedCategory, setSelectedCategory] = useState('');
  const [loading, setLoading] = useState(true);
  
  const navigate = useNavigate(); // 2. Инициализируем navigate

  const fetchCatalogData = async (searchQuery = '', categoryId = '') => {
    setLoading(true);
    try {
      let url = 'products/?';
      if (searchQuery) url += `search=${searchQuery}&`;
      if (categoryId) url += `category=${categoryId}&`;

      const [prodRes, catRes] = await Promise.all([
        api.get(url),
        api.get('categories/')
      ]);

      setProducts(prodRes.data.results || prodRes.data);
      setCategories(catRes.data.results || catRes.data);
    } catch (err) {
      console.error('Ошибка загрузки каталога', err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchCatalogData();
  }, []);

  const handleSearchSubmit = (e) => {
    e.preventDefault();
    fetchCatalogData(search, selectedCategory);
  };

  const handleCategoryChange = (catId) => {
    setSelectedCategory(catId);
    fetchCatalogData(search, catId);
  };

  return (
    <div style={{ maxWidth: '1200px', margin: '0 auto', padding: '20px' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '25px' }}>
        <h2>Каталог товаров</h2>
        
        <form onSubmit={handleSearchSubmit} style={{ display: 'flex', gap: '10px' }}>
          <input 
            type="text" 
            placeholder="Поиск товаров..." 
            value={search}
            onChange={(e) => setSearch(e.target.value)}
            style={{ padding: '8px 12px', width: '250px', borderRadius: '4px', border: '1px solid #ced4da' }}
          />
          <button type="submit" style={{ padding: '8px 16px', background: '#007bff', color: '#fff', border: 'none', borderRadius: '4px', cursor: 'pointer' }}>
            Найти
          </button>
        </form>
      </div>

      <div style={{ display: 'flex', gap: '10px', marginBottom: '25px', overflowX: 'auto', paddingBottom: '5px' }}>
        <button 
          onClick={() => handleCategoryChange('')}
          style={{ 
            padding: '6px 14px', 
            borderRadius: '20px', 
            border: '1px solid #ced4da', 
            background: selectedCategory === '' ? '#007bff' : '#fff', 
            color: selectedCategory === '' ? '#fff' : '#333',
            cursor: 'pointer' 
          }}
        >
          Все категории
        </button>
        {categories.map((cat) => (
          <button 
            key={cat.id}
            onClick={() => handleCategoryChange(cat.id)}
            style={{ 
              padding: '6px 14px', 
              borderRadius: '20px', 
              border: '1px solid #ced4da', 
              background: Number(selectedCategory) === cat.id ? '#007bff' : '#fff', 
              color: Number(selectedCategory) === cat.id ? '#fff' : '#333',
              cursor: 'pointer' 
            }}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {loading ? (
        <div style={{ textAlign: 'center', padding: '40px', color: '#666' }}>Загрузка каталога...</div>
      ) : (
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(260px, 1fr))', gap: '20px' }}>
          {products.length > 0 ? (
            products.map((product) => (
              <div 
                key={product.id} 
                onClick={() => navigate(`/products/${product.id}`)} // 3. Вешаем переход на клик по карточке!
                style={{ 
                  border: '1px solid #e0e0e0', 
                  borderRadius: '8px', 
                  padding: '20px', 
                  background: '#fff', 
                  boxShadow: '0 4px 6px rgba(0,0,0,0.02)',
                  display: 'flex',
                  flexDirection: 'column',
                  justifyContent: 'space-between',
                  cursor: 'pointer', // Курсор в виде указателя
                  transition: 'transform 0.2s, box-shadow 0.2s'
                }}
              >
                <div>
                  <h3 style={{ margin: '0 0 10px 0', fontSize: '18px', color: '#212529' }}>{product.title}</h3>
                  <p style={{ color: '#6c757d', fontSize: '14px', lineHeight: '1.4', marginBottom: '15px', height: '40px', overflow: 'hidden' }}>
                    {product.description}
                  </p>
                </div>
                <div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '10px' }}>
                    <span style={{ fontWeight: 'bold', fontSize: '18px', color: '#28a745' }}>{product.price} ₾</span>
                  </div>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '12px', color: '#adb5bd', borderTop: '1px solid #f1f3f5', paddingTop: '10px' }}>
                    <span>Продавец: {product.owner?.username || 'Магазин'}</span>
                    <span>{new Date(product.created_at).toLocaleDateString()}</span>
                  </div>
                </div>
              </div>
            ))
          ) : (
            <div style={{ gridColumn: '1 / -1', textAlign: 'center', padding: '40px', color: '#666', background: '#fff', borderRadius: '8px', border: '1px solid #e0e0e0' }}>
              <p style={{ fontSize: '16px', margin: 0 }}>Товары не найдены</p>
            </div>
          )}
        </div>
      )}
    </div>
  );
};

export default Catalog;
